const SB_URL = $env.SUPABASE_URL;
const SB_KEY = $env.SUPABASE_SERVICE_ROLE_KEY;
const http = this.helpers.httpRequest;
if (!SB_URL || !SB_KEY) return [{ json: { skipped: true, reason: 'SUPABASE_URL / SUPABASE_SERVICE_ROLE_KEY not set' } }];

function rest(path, opts) {
  opts = opts || {};
  return http(Object.assign({ url: SB_URL + '/rest/v1/' + path, json: true }, opts, {
    headers: Object.assign({ apikey: SB_KEY, Authorization: 'Bearer ' + SB_KEY, 'Content-Type': 'application/json' }, opts.headers || {}),
  }));
}
function normDomain(d) { if (!d) return ''; return String(d).toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '').trim(); }
function textIncludes(t, n) { if (!t || !n) return false; return String(t).toLowerCase().includes(String(n).toLowerCase()); }
function sameUrl(a, b) {
  if (!a || !b) return false;
  const na = String(a).replace(/\/$/, '').toLowerCase();
  const nb = String(b).replace(/\/$/, '').toLowerCase();
  return na === nb || na.indexOf(nb) === 0 || nb.indexOf(na) === 0;
}

const live = await rest('citation_targets?select=id,entity_id,citation_url,name,tracked_entities(name,domain)&status=eq.live&citation_url=not.is.null');
if (!live.length) return [{ json: { note: 'no live citations to verify' } }];

const checks = await rest('visibility_checks?select=source_urls');
const allSourceUrls = [];
for (const ch of checks) { const u = Array.isArray(ch.source_urls) ? ch.source_urls : []; for (const x of u) allSourceUrls.push(x); }

const out = [];
const mentionRows = [];
for (const t of live) {
  const ent = Array.isArray(t.tracked_entities) ? t.tracked_entities[0] : t.tracked_entities;
  const name = ent && ent.name ? ent.name : '';
  const dom = ent && ent.domain ? normDomain(ent.domain) : '';
  let isLive = false;
  let note = '';
  try {
    const html = await http({ url: t.citation_url, json: false, headers: { 'User-Agent': 'LIT-VisibilityEngine/1.0' } });
    const text = String(html).replace(/<[^>]+>/g, ' ');
    isLive = textIncludes(text, name) || (dom && textIncludes(text, dom));
    note = isLive ? 'citation_url resolves and still mentions us' : 'citation_url resolves but mention not found';
  } catch (e) {
    isLive = false;
    note = 'citation_url did not resolve: ' + String((e && e.message) || e);
  }
  const seenInAi = allSourceUrls.some((u) => sameUrl(u, t.citation_url));
  if (seenInAi) note += '; appears in probe source_urls (feeding AI answers)';
  mentionRows.push({ citation_target_id: t.id, is_live: isLive, seen_in_ai: seenInAi, note: note });
  out.push({ json: { target: t.name, citation_url: t.citation_url, is_live: isLive, seen_in_ai: seenInAi } });
}
if (mentionRows.length) {
  await rest('mention_checks', { method: 'POST', headers: { Prefer: 'return=minimal' }, body: mentionRows });
}
return out;
